-- -----------------------------------------------------------------------------
-- profiles
-- -----------------------------------------------------------------------------
CREATE TABLE `profiles` (
  `id` CHAR(36) NOT NULL,
  `role` VARCHAR(255) NOT NULL DEFAULT 'courier',
  CONSTRAINT `chk_profiles_role` CHECK (`role` IN ('courier', 'store_owner', 'admin')),
