  `current_longitude` DOUBLE NULL,
  `last_location_at` DATETIME(6) NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `moderation_status` VARCHAR(255) NOT NULL DEFAULT 'pending',
  CONSTRAINT `chk_couriers_moderation_status` CHECK (`moderation_status` IN ('pending', 'active', 'suspended', 'banned', 'rejected')),
  `moderation_reason` TEXT NULL,
  `moderated_at` DATETIME(6) NULL,
  `moderated_by` CHAR(36) NULL,
  `approved_at` DATETIME(6) NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

